<div x-show="indicador" x-cloak x-transition.opacity class="rm-modal-shell rm-operation-help fixed inset-0 flex items-center justify-center p-4 is-open" x-trap.inert.noscroll="indicador !== null" @keydown.escape.window="if(indicador) cerrarIndicador()" role="dialog" aria-modal="true" aria-labelledby="indicador-titulo">
    <button type="button" class="rm-modal-shell__overlay" tabindex="-1" aria-label="Cerrar indicador" @click="cerrarIndicador()"></button>
    <section class="rm-modal-panel relative"><header class="rm-modal-header"><div><p class="rm-residents-eyebrow">Lectura del reporte</p><h2 id="indicador-titulo" x-text="indicador?.titulo"></h2></div><button type="button" x-ref="cerrarIndicador" class="rm-btn-icon" aria-label="Cerrar indicador" @click="cerrarIndicador()"><i class="ph-bold ph-x" aria-hidden="true"></i></button></header><div class="rm-modal-body"><div class="rm-operation-count"><strong x-text="indicador?.total"></strong><span x-text="indicador?.actual ? 'camas ocupadas ahora' : 'registros en el periodo'"></span></div><p><strong>Se cuenta por:</strong> <span x-text="indicador?.fuente"></span></p><p x-show="!indicador?.actual"><strong>Periodo:</strong> <span x-text="indicador?.desde"></span> — <span x-text="indicador?.hasta"></span></p><p class="rm-control-help" x-text="indicador?.actual ? 'Es la situación vigente al consultar; no depende del periodo.' : 'Cada indicador representa un proceso distinto. Estos conteos no se suman como personas únicas.'"></p></div><footer class="rm-modal-footer"><button type="button" class="rm-btn-primary" @click="cerrarIndicador()">Entendido</button></footer></section>
</div>
